package com.primehr.succession.api;

import com.primehr.security.*;
import com.primehr.succession.application.SuccessionContinuityService;
import com.primehr.succession.api.SuccessionContinuityDtos.*;
import jakarta.validation.Valid;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/primehr/v1/succession/continuity")
public class SuccessionContinuityController {
    private final SuccessionContinuityService service; private final SuccessionPlanningPermissionGuard permission; private final AgencyScopeResolver agency;
    public SuccessionContinuityController(SuccessionContinuityService service,SuccessionPlanningPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}
    @GetMapping("/plans") public List<PlanResponse>plans(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.ACCESS,t);return service.listPlans(agency.resolveAgencyId(a),a.getName(),s);}
    @GetMapping("/plans/{id}") public PlanResponse plan(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.ACCESS,t);return service.getPlan(agency.resolveAgencyId(a),id,a.getName(),s);}
    @PostMapping("/risk-reviews/{riskId}/plans") @ResponseStatus(HttpStatus.CREATED) public PlanResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String riskId,@Valid@RequestBody PlanInput i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.ADD,t);return service.createPlan(agency.resolveAgencyId(a),riskId,i,a.getName(),s,c);}
    @PutMapping("/plans/{id}") public PlanResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody PlanInput i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.EDIT,t);return service.updatePlan(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/plans/{id}/submission") public PlanResponse submit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody VersionInput i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.SUBMIT,t);return service.submitPlan(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/plans/{id}/approval") public PlanResponse approve(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody DecisionInput i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.APPROVE,t);return service.approvePlan(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/plans/{id}/finalization") public PlanResponse finalizePlan(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody VersionInput i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.FINALIZE,t);return service.finalizePlan(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @GetMapping("/referrals") public List<ReferralResponse>referrals(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.ACCESS,t);return service.listReferrals(agency.resolveAgencyId(a),a.getName(),s);}
    @GetMapping("/referrals/{id}") public ReferralResponse referral(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.ACCESS,t);return service.getReferral(agency.resolveAgencyId(a),id,a.getName(),s);}
    @PostMapping("/plans/{planId}/referrals") @ResponseStatus(HttpStatus.CREATED) public ReferralResponse createReferral(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String planId,@Valid@RequestBody ReferralCreate i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.ADD,t);return service.createReferral(agency.resolveAgencyId(a),planId,i,a.getName(),s,c);}
    @PutMapping("/referrals/{id}") public ReferralResponse updateReferral(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReferralUpdate i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.EDIT,t);return service.updateReferral(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/referrals/{id}/vacancy-link") public ReferralResponse linkVacancy(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody VacancyLink i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.EDIT,t);return service.linkVacancy(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/referrals/{id}/authorization") public ReferralResponse authorizeReferral(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReferralTransition i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.APPROVE,t);return service.authorizeReferral(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/referrals/{id}/dispatch") public ReferralResponse sendReferral(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReferralTransition i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.SUBMIT,t);return service.sendReferral(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/referrals/{id}/receipt") public ReferralResponse receiveReferral(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReferralTransition i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.FINALIZE,t);return service.receiveReferral(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/referrals/{id}/status") public ReferralResponse status(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReferralStatus i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.FINALIZE,t);return service.updateReferralStatus(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
    @PostMapping("/referrals/{id}/withdrawal") public ReferralResponse withdraw(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReferralTransition i){var s=permission.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.EDIT,t);return service.withdrawReferral(agency.resolveAgencyId(a),id,i,a.getName(),s,c);}
}
